import fs from 'node:fs';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
import {hash,json} from './seal-simple-website-successor.mjs';import {memoryGate} from './native-website-integration-stage-20261025.mjs';
import {stage,site,prep,parent,save,verify,update} from './canonical-body-learning-integration-20261025.mjs';
const memory=memoryGate(1024),state=verify();assert.equal(state.phase,'feature-edited-unbound');assert(json(stage+'/checks/unit-after-attempt-1/RESULT.json').passing);
const dir=stage+'/checks/bind-attempt-1';assert(!fs.existsSync(dir));fs.mkdirSync(dir,{recursive:true});
const old=json(site+'/atlas-review/integration-inputs.json'),oldManifest=json(site+'/atlas-review/manifest.json'),oldBody=json(site+'/atlas-review/content/body-renderer-revision.json'),oldShoulder=json(site+'/atlas-review/content/review-revisions.json');assert.equal(old.sha256,prep.oldReviewBinding);assert.equal(old.inputs.length,1808);
const env=Object.fromEntries(Object.entries(process.env).filter(([k])=>/^(path|systemroot|windir|comspec|pathext|temp|tmp|os|processor_architecture|number_of_processors)$/i.test(k)));Object.assign(env,{NODE_OPTIONS:'--max-old-space-size=256',GIT_OPTIONAL_LOCKS:'0',GIT_NO_REPLACE_OBJECTS:'1'});
const result=spawnSync(process.execPath,['--max-old-space-size=256','scripts/bind-clinical-review.mjs'],{cwd:site,env,windowsHide:true,maxBuffer:2*1024*1024,encoding:'utf8'});fs.writeFileSync(dir+'/stdout.log',result.stdout??'',{flag:'wx'});fs.writeFileSync(dir+'/stderr.log',result.stderr??'',{flag:'wx'});
const paths=['atlas-review/manifest.json','atlas-review/integration-inputs.json','atlas-review/content/body-renderer-revision.json','atlas-review/content/review-revisions.json'];
if(result.status!==0||result.signal||result.error){update(state,'binding-failed',paths,{coherentDelivery:false});save(dir+'/FAILURE.json',{at:new Date().toISOString(),code:result.status,signal:result.signal,error:result.error?String(result.error):null,partialGeneratedChangesCaptured:true});throw Error('Stock binding failed; preserve actual partial state');}
const binding=json(site+'/atlas-review/integration-inputs.json'),manifest=json(site+'/atlas-review/manifest.json'),body=json(site+'/atlas-review/content/body-renderer-revision.json'),shoulder=json(site+'/atlas-review/content/review-revisions.json'),sha=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
assert.equal(binding.sourceCommit,parent.atlasHead);assert.equal(binding.inputs.length,1809);assert.equal(new Set(binding.inputs.map(r=>r.path)).size,1809);assert.equal(binding.sha256,sha(binding.inputs));assert.notEqual(binding.sha256,old.sha256);
const changed=[];for(const r of old.inputs){const found=binding.inputs.filter(n=>n.path===r.path);assert.equal(found.length,1);assert.equal(found[0].sha256,hash(site+'/'+r.path),r.path);if(found[0].sha256!==r.sha256)changed.push(r.path);}
assert.deepEqual(changed.sort(),['components/AtlasBodyLearning.tsx','scripts/bind-clinical-review.mjs'].sort());assert.deepEqual(binding.inputs.filter(r=>!old.inputs.some(o=>o.path===r.path)),[{path:'components/atlas-runtime-state.ts',sha256:hash(site+'/components/atlas-runtime-state.ts')}]);
const expectedManifest=structuredClone(oldManifest);expectedManifest.websiteIntegrationSha256=binding.sha256;for(const r of expectedManifest.files)if(['content/body-renderer-revision.json','content/review-revisions.json'].includes(r.path))r.importedSha256=hash(site+'/atlas-review/'+r.path);assert.deepEqual(manifest,expectedManifest);
const expectedBody=structuredClone(oldBody);expectedBody.sourceRendererSha256??=oldBody.sha256;expectedBody.websiteIntegrationSha256=binding.sha256;expectedBody.sha256=sha({source:expectedBody.sourceRendererSha256,website:binding.sha256});assert.deepEqual(body,expectedBody);
const expectedShoulder=structuredClone(oldShoulder);expectedShoulder.sourceRevisions??=structuredClone(oldShoulder.revisions);expectedShoulder.websiteIntegrationSha256=binding.sha256;for(const [id,tracks]of Object.entries(expectedShoulder.sourceRevisions))for(const track of ['geometry','teaching'])expectedShoulder.revisions[id][track]=tracks[track]===null?null:sha({source:tracks[track],website:binding.sha256});assert.deepEqual(shoulder,expectedShoulder);
const next=update(state,'bound',paths,{reviewBindingSha256:binding.sha256,reviewInputCount:1809,coherentDelivery:false,sourceRendererSha256:body.sourceRendererSha256,sourceRevisionsPreserved:true,savedDecisionsReadOrMigrated:false});verify(next);
save(dir+'/TERMINAL.json',{at:new Date().toISOString(),memory,code:0,passing:true,oldBinding:old.sha256,newBinding:binding.sha256,inputCount:1809,changedExistingInputs:changed,addedInput:'components/atlas-runtime-state.ts',sourceRevisionFormulaePreserved:true,sourceRendererSha256:body.sourceRendererSha256,savedDecisionsReadOrMigrated:false,viewerAndPinStillPending:true,ownerPreviewChanged:false});console.log(JSON.stringify({terminal:dir+'/TERMINAL.json',sha256:hash(dir+'/TERMINAL.json'),passing:true,binding:binding.sha256,inputCount:1809,sourceRevisionsPreserved:true,coherentDelivery:false}));
